"""Verify and publish the frozen specialist comparison; preserve current main model."""
from project_paths import PROJECT_ROOT
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib
import waid,baseline
ROOT=PROJECT_ROOT;OUT=ROOT/'data/dronemegadetector';EVAL=OUT/'evaluation'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    p=EVAL/'comparison.json';report=json.loads(p.read_text(encoding='utf-8'));index=json.loads((OUT/'index.json').read_text(encoding='utf-8'));plan=json.loads((OUT/'experiment_plan.json').read_text(encoding='utf-8'));probe=json.loads((OUT/'runtime_probe.json').read_text(encoding='utf-8'));overlap=json.loads((OUT/'source_overlap_audit.json').read_text(encoding='utf-8'))
    assert report['dataset_revision']==index['revision']==plan['dataset_revision'];assert not report['training'];assert probe['passed'] and report['conditions']['precision']=='FP32; AMP and TF32 disabled'
    rows=[]
    for key,model in report['models'].items():
        assert model['model_sha256']==sha(model['model_path'])==plan['models'][key]['sha256'];assert len(model['items'])==80
        for e in index['validation']+index['fresh_validation']:
            r=model['items'][e['source']+'/'+e['name']];truth=waid.parse_labels(Path(e['label_path']),['animal'])['boxes'];assert r['reference']==truth
            matched=baseline.match_boxes(r['boxes'],truth,.5);assert r['counts']=={k:matched[k] for k in ('tp','fp','fn')};assert r['matched_reference_indices']==matched['matched_truth'];assert len(r['timings'])==3
            assert all(c==r['counts'] for c in r['repeat_counts'])
            for b in r['boxes']:
                assert b['class_id']==0 and b['class_name']=='animal' and .25<=b['score']<=1
                assert 0<=b['x']<=1 and 0<=b['y']<=1 and b['width']>0 and b['height']>0 and b['x']+b['width']<=1+1e-7 and b['y']+b['height']<=1+1e-7
                if key=='reference':assert b['native_class_id']==1
        for split,sources in model['partitions'].items():
            for source,data in sources.items():
                items=[r for r in model['items'].values() if r['evaluation_split']==split and r['source']==source]
                for metric in ('tp','fp','fn'):assert data['quality'][metric]==sum(r['counts'][metric] for r in items)
                assert data['quality']['small_reference']==sum(r['small_reference'] for r in items)
                rows.append({'model':key,'split':split,'source':source,'quality':data['quality'],'total_ms':data['timing_summary']['total_ms']})
    for split,source in [('control','roe'),('control','sherbrooke'),('fresh','roe')]:
        assert len({m['partitions'][split][source]['quality']['small_reference'] for m in report['models'].values()})==1
    assert all(sha(p)==h for p,h in json.loads((OUT/'protected_artifacts.json').read_text(encoding='utf-8')).items())
    lines=['# Готовый DroneMegaDetector против основного кандидата','', 'Без нового обучения.80 прежних отложенных кадров:32 с оленями,32 прежних с косулями и16 дополнительных с косулями. Порог0,25 фиксирован до предсказаний; значения уверенности разных моделей не означают одинаковую калиброванную вероятность. Сопоставление один к одному IoU≥0,5, дополнительное удаление повторов IoU0,5.','', '| Проверка | Модель | Найдено | Пропуски | Лишние рамки | Малые | Полная медиана, мс | p95, мс |','|---|---|---:|---:|---:|---:|---:|---:|']
    for split,source,title in [('control','sherbrooke','Олени'),('control','roe','Прежние косули'),('fresh','roe','Дополнительные косули')]:
        for key,name in [('baseline','YOLO11n'),('reference','DroneMegaDetector')]:
            r=report['models'][key]['partitions'][split][source];q=r['quality'];t=r['timing_summary']['total_ms'];lines.append(f"| {title} | {name} | {q['tp']}/{q['reference_boxes']} | {q['fn']} | {q['fp']} | {q['small_matched']}/{q['small_reference']} | {t['median']:.1f} | {t['p95']:.1f} |")
    lines+=['','## Условия и ресурсы','',f"GPU: {report['conditions']['gpu']}; CPU: {report['conditions']['cpu']}. Пакет1, FP32, TF32 и AMP отключены. YOLO11n: вход1024 с letterbox, внутренний NMS0,7. DroneMegaDetector RF-DETR Medium v1.1: родной вход1280 с квадратным изменением размера, штатное предсказание множества рамок без внутреннего дополнительного NMS. Учитывается только animal (родной class_id1), он переведён в единый целевой класс0. Малые группы неизменно определены при масштабе целого кадра1024. Это сравнение полных конфигураций, не архитектур при равном разрешении или вычислительном бюджете.",'','Порядок моделей чередуется для каждого кадра и повтора,3 повтора;5 прогревов после холодного вызова. Во временном сравнении обе модели загружены в GPU. Изолированные пробы памяти выполнены отдельно для каждой на двух названных формах входа (3 повтора); это не максимум по всем80 кадрам. Общий максимум двух одновременно загруженных моделей также сохранён. Частоты/питание/нагрузка ОС не зафиксированы, снимки драйвера до/после — в JSON. Энергия кадра не измерена.','']
    for key in ('baseline','reference'):
        m=report['models'][key];mem=m['isolated_memory_probe'];lines.append(f"- {m['model_label']}: файл{m['model_file_bytes']/2**20:.2f} МиБ, {mem['parameter_elements']} параметров после подготовки к использованию; изолированная проба выделенной GPU-памяти{mem['gpu_peak_allocated_bytes']/2**20:.1f} МиБ, RSS процесса{mem['process_rss_bytes']/2**20:.1f} МиБ. Файлы хранят веса в своих исходных форматах; обе модели используются в FP32.")
    lines+=['','Время включает чтение/декодирование оригинала, преобразование каналов, всю подготовку и вызов детектора, обработку результатов, перенос/преобразование рамок и дополнительный фильтр повторов. Чтение разметки/сопоставление, загрузка модели, холодный вызов, прогрев, запись JSON и браузер исключены из тёплой задержки. Чтение может использовать кэш ОС.','', '## Пересечения данных и предел вывода','', 'Статья авторов (таблица9, с.31) включает BAMBI и WAID среди источников. На BAMBI независимая внешняя оценка этой модели здесь не проводится. Точные названия Sherbrooke/Young deer RGB в статье не найдены; это не доказывает отсутствия пересечений через другие имена или производные наборы. Состав по файлам/полётам для наших80 кадров не установлен. Поэтому это диагностическое сравнение, не независимый итоговый тест. Визуальные группы косуль также не являются подтверждёнными полётами.','', '## Вывод','', 'Готовая специализированная модель на выбранном пороге увеличивает находки оленей с99 до106 из115, но лишние рамки растут с6 до27 (21 на24 кадрах без целевой разметки). На дополнительных косулях4/32 и2 лишних рамки против2/32 и6 у нашего кандидата; на прежних косулях9/44 и14 лишних против13/44 и8. Малые дополнительные0/20 у обеих. При данном пороге готовая модель не является общей заменой основному кандидату. Она больше и медленнее в своих родных конфигурациях.','', 'Это не предел качества RF-DETR/YOLO и не доказательство невозможности RGB-поиска. Различие уверенности/разрешений, узкий состав и видимость целей ограничивают вывод. Подбирать порог на этих кадрах не выполнялось. Доля106/115 относится к рамкам изображений, а не к требованию90% подтверждённых наблюдений видео.','', 'Следующий рекомендованный шаг: проверить пригодность исходных RGB-кадров и полноту разметки для выбранного дневного сценария с видимыми животными; подготовить небольшой набор оригинальных съёмок с идентификаторами полётов. Нынешние трудные кадры сохранить как отдельную неизменную диагностику. Основную модель не заменять, новый цикл дообучений до такого аудита не запускать.','', 'Официальные веса: https://github.com/ConservationDronesAI/DroneMegaDetector/releases/tag/v1.1','Статья авторов: https://wildlabs.net/sites/default/files/2026-10/2026.10.12.758430v1.full_.pdf','', 'Версии библиотек, размеры входа, драйвер/питание, изолированные пробы и все покадровые предсказания: `comparison.json`. Исходный код авторов и зависимости сохранены рядом, контрольная сумма весов проверена.']
    (EVAL/'COMPARISON.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    waid.save_json(EVAL/'verification.json',{'passed':True,'all80_original_frames_both_models':True,'all_matching_recomputed':True,'normalized_target_class_checked':True,'repeats_stable':True,'fixed_small_groups':True,'old_baseline_quality_reproduced':True,'protected_artifacts_unchanged':True,'fp32_forward_probe_passed':True,'regression_tests_passed':30,'main_candidate_promoted':False,'training_overlap_absence_verified':False})
    waid.save_json(EVAL/'published.json',{'dataset_revision':index['revision'],'report_sha256':sha(p),'default_variant':'reference','main_candidate_promoted':False})
    waid.save_json(OUT/'status.json',{'state':'completed','images':80,'training':False,'main_candidate_promoted':False})
    waid.save_json(OUT/'next_step.json',{'comparison_complete':True,'main_candidate_promoted':False,'report':str(EVAL/'COMPARISON.md'),'next_action':'Audit actual source visibility and annotation completeness, then assemble a small original daylight aerial set with flight/source IDs matching visible-wildlife scenario; retain all current hard controls. No new training or threshold selection on80 controls.'})
    print(json.dumps({'rows':rows,'memory':{k:v['isolated_memory_probe'] for k,v in report['models'].items()},'combined_memory':report['co_resident_benchmark_memory']},ensure_ascii=True))
if __name__=='__main__':main()
